  ('60b29a54-daea-43af-9ee8-ae3e49fc5586', 'edf74d59-6463-49c8-82d1-b5ebc1fd6097', null, 'topic'::public.curated_course_node_type, 'Physical Modeling, Measurement, Units, and Uncertainty', 'Students begin by learning how physics turns messy reality into measured quantities, models, estimates, and testable claims.', 0),
  ('45a88664-ec06-470c-b8d6-6f13e80491fc', 'edf74d59-6463-49c8-82d1-b5ebc1fd6097', '60b29a54-daea-43af-9ee8-ae3e49fc5586', 'subtopic'::public.curated_course_node_type, 'Models and approximations', 'The point is to learn that physics is built from idealized models chosen for a purpose.', 0),
